from solution import is_simple_power
import pytest
from hypothesis import given, strategies as st


# ---- obviously-correct reference model (written from spec only) ----
def _ref(x: int, n: int) -> bool:
    # True iff exists integer k with n**k == x (Python ** semantics, 0**0 == 1).
    # k == 0 gives 1 for any n (including 0), so x == 1 is always True.
    if x == 1:
        return True
    # k < 0: for n == 0 undefined -> no; for n != 0 need x * n**j == 1 with j>0.
    # That requires |x| == 1, already handled (x==1 True, x==-1 handled below).
    # Check it explicitly with exact integer arithmetic for completeness.
    if x == -1:
        # (-1)**1 == -1, so True iff n == -1; otherwise check negative-k case:
        # x * n**j == 1 -> -n**j == 1 -> n**j == -1 -> only possible for n == -1.
        return n == -1
    # Now |x| != 1.
    if n == 0:
        # 0**0 == 1 (handled), 0**k>0 == 0, 0**k<0 undefined.
        return x == 0
    if n == 1:
        return False  # 1**k == 1 != x
    if n == -1:
        return False  # (-1)**k in {1,-1}, x not in there
    if x == 0:
        return False  # only 0**k>0 == 0, but n != 0 here
    # Remaining: |n| >= 2, |x| >= 2. Negative k gives |x * n**j| >= 2*2 > 1.
    for j in range(1, 64):
        if abs(n) ** j > abs(x) and abs(x) > 0:
            # for larger j, |x * n**j| only grows, can never be 1
            break
        if x * (n ** j) == 1:
            return True
    # Non-negative k >= 1 by direct exponentiation with early cutoff.
    for k in range(1, 128):
        v = pow(n, k)
        if v == x:
            return True
        if abs(v) > abs(x):
            # |n| >= 2 so magnitude strictly grows from here
            break
    return False


# ---- concrete examples from the spec ----
@pytest.mark.parametrize("x,n,expected", [
    (1, 4, True),
    (2, 2, True),
    (8, 2, True),
    (3, 2, False),
    (3, 1, False),
    (5, 3, False),
])
def test_spec_examples(x, n, expected):
    assert is_simple_power(x, n) is expected


def test_x_equals_n_always_true():
    for v in [-10, -2, -1, 0, 1, 2, 3, 10, 100]:
        assert is_simple_power(v, v) is True


def test_one_is_power_of_anything():
    for n in [-10, -2, -1, 0, 1, 2, 4, 100]:
        assert is_simple_power(1, n) is True


# ---- properties ----
@given(n=st.integers(min_value=-20, max_value=20))
def test_property_x_one_always_true(n):
    assert is_simple_power(1, n) is True


@given(x=st.integers(min_value=-1000, max_value=1000))
def test_property_n_one_iff_x_one(x):
    assert is_simple_power(x, 1) is (x == 1)


@given(x=st.integers(min_value=-1000, max_value=1000))
def test_property_n_minus_one(x):
    assert is_simple_power(x, -1) is (x == 1 or x == -1)


@given(n=st.integers(min_value=-20, max_value=20))
def test_property_x_zero_iff_n_zero(n):
    assert is_simple_power(0, n) is (n == 0)


@given(x=st.integers(min_value=-1000, max_value=1000),
       n=st.integers(min_value=0, max_value=20))
def test_property_negative_x_never_power_of_nonnegative_n(x, n):
    # n >= 0 implies n**k >= 0 for all defined k (0**0==1), so negative x is False.
    if x < 0:
        assert is_simple_power(x, n) is False


@given(n=st.integers(min_value=-20, max_value=20))
def test_property_self_power(n):
    # n**1 == n
    assert is_simple_power(n, n) is True


@given(n=st.integers(min_value=-20, max_value=20))
def test_property_n_squared_is_power(n):
    assert is_simple_power(n * n, n) is True


@given(x=st.integers(min_value=-500, max_value=500),
       n=st.integers(min_value=-10, max_value=10))
def test_property_matches_reference_small(x, n):
    assert is_simple_power(x, n) is _ref(x, n)


@given(b=st.integers(min_value=-6, max_value=6),
       e=st.integers(min_value=0, max_value=10))
def test_property_constructed_powers_are_true(b, e):
    x = pow(b, e)  # Python semantics, includes 0**0 == 1
    assert is_simple_power(x, b) is True


@given(b=st.integers(min_value=2, max_value=5),
       e=st.integers(min_value=1, max_value=8))
def test_property_next_after_power_is_false(b, e):
    # b**e + 1 lies strictly between consecutive powers for b >= 2
    x = pow(b, e) + 1
    # x == 1 impossible here since b**e >= 2
    assert is_simple_power(x, b) is False


@given(b=st.integers(min_value=-5, max_value=-2),
       e=st.integers(min_value=1, max_value=9))
def test_property_negative_base_powers_true(b, e):
    assert is_simple_power(pow(b, e), b) is True


@given(x=st.integers(min_value=-500, max_value=500),
       n=st.integers(min_value=-10, max_value=10))
def test_property_returns_bool(x, n):
    r = is_simple_power(x, n)
    assert r is True or r is False


@given(x=st.integers(min_value=2, max_value=500),
       n=st.integers(min_value=2, max_value=10))
def test_property_true_implies_divisible(x, n):
    # for |n| >= 2, |x| > 1: n**k == x with k>=1 implies x % n == 0
    if is_simple_power(x, n) is True and x != 1:
        assert x % n == 0
